package main

import (
	"context"
	"fmt"
	"time"

	lua "github.com/yuin/gopher-lua"
)

const (
	// maxLuaMemory limits the Lua VM memory to prevent resource exhaustion.
	maxLuaMemory = 1 * 1024 * 1024 // 1 MB
	// timeout limits the total execution time for a script.
	timeout = 500 * time.Millisecond
)

// openSafeLibs opens only the safe Lua standard libraries (base, math, table, string).
// IO, OS, debug, and package libraries are omitted to prevent dangerous operations.
func openSafeLibs(L *lua.LState) {
	lua.OpenBase(L)
	lua.OpenMath(L)
	lua.OpenTable(L)
	lua.OpenString(L)
}

// ExecutePricingScript executes a user‑provided Lua script to calculate the final price
// of a product based on the given context.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state without pre‑loading any libraries.
	L := lua.NewState(lua.Options{SkipOpenLibs: true})
	defer L.Close()

	// Open only safe libraries.
	openSafeLibs(L)

	// Set a memory limit to avoid excessive memory consumption.
	L.SetMx(maxLuaMemory)

	// Use a timeout context to interrupt long‑running or infinite scripts.
	ctxTimeout, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	L.SetContext(ctxTimeout)

	// Run the user script to define the required global function.
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Retrieve the calculate_final_price function from the global scope.
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function or not defined")
	}

	// Convert the Go context map into a Lua table.
	ctxTable := L.NewTable()
	for k, v := range ctx {
		L.SetField(ctxTable, k, lua.LNumber(v))
	}

	// Call the Lua function in protected mode, expecting one return value.
	if err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable); err != nil {
		return 0, fmt.Errorf("failed to call calculate_final_price: %w", err)
	}

	// Extract the return value and clean the stack.
	result := L.Get(-1)
	L.Pop(1)

	if result.Type() != lua.LTNumber {
		return 0, fmt.Errorf("calculate_final_price did not return a number")
	}

	return float64(result.(lua.LNumber)), nil
}

