	lua.OpenBase(L)   // provides assert, error, ipairs, next, pairs, select, tonumber, tostring, type, etc.
	lua.OpenString(L) // string manipulation
	lua.OpenTable(L)  // table manipulation
	lua.OpenMath(L)   // math functions (needed for price calculations)

	// Remove dangerous functions from the base library
	L.SetGlobal("load", lua.LNil)     // prevents dynamic code loading
	L.SetGlobal("loadfile", lua.LNil) // prevents loading external files

	// Set a timeout context to abort runaway scripts (e.g., infinite loops).
	timeoutCtx, cancel := context.WithTimeout(context.Background(), 1*time.Second)
	defer cancel()
	L.SetContext(timeoutCtx)

	// Load and execute the user-provided script.
	// The script is expected to define a global function calculate_final_price.
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Retrieve the calculate_final_price function from global scope.
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
