// ExecutePricingScript runs a user-provided Lua script to compute the final price.
// The script must define a global function `calculate_final_price(ctx)` that
// accepts a table and returns a number.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	L := lua.NewState()
	defer L.Close()

	// Load and execute the Lua script to define the function.
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to parse script: %w", err)
	}

	// Retrieve the global function.
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("global 'calculate_final_price' is not a function (type: %s)", fn.Type().String())
	}

	// Push the function and build the context table.
	L.Push(fn)

	tbl := L.NewTable()
	for k, v := range ctx {
		L.SetField(tbl, k, lua.LNumber(v))
	}
	L.Push(tbl)

	// Call the function: 1 argument, 1 result.
	if err := L.PCall(1, 1, nil); err != nil {
