	}

	// Open safe libraries needed for most scripts.
	lua.OpenMath(L)
	lua.OpenTable(L)
	lua.OpenString(L)

	// Load and execute the script (within the timeout).
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

