func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	L := lua.NewState()
	defer L.Close()

	// Convert the Go map into a Lua table
	ctxTable := L.NewTable()
	for k, v := range ctx {
		L.SetField(ctxTable, k, lua.LNumber(v))
	}

	// Execute the provided Lua script to define the global function
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}
	L.SetTop(0) // clean the stack from any leftover values

	// Retrieve the global function
	L.GetGlobal("calculate_final_price")
	if L.Get(-1).Type() != lua.LTFunction {
		L.Pop(1) // remove the non-function value
		return 0, fmt.Errorf("calculate_final_price is not defined or is not a function")
	}

	// Push the context table as the function argument
	L.Push(ctxTable)

	// Call calculate_final_price with 1 argument and accept multiple return values
	if err := L.PCall(1, lua.MultRet, nil); err != nil {
		return 0, fmt.Errorf("error calling calculate_final_price: %w", err)
	}

	// Retrieve the return value(s)
	nret := L.GetTop()
	if nret == 0 {
		return 0, fmt.Errorf("calculate_final_price did not return a value")
	}
	// The first return value is at index 1 (the bottom of the returned values)
	ret := L.Get(1)
	// No explicit Pop needed; the Lua state will be closed and cleaned up.

	if num, ok := ret.(lua.LNumber); ok {
		return float64(num), nil
	}

	return 0, fmt.Errorf("expected a number return value, got %s", ret.Type().String())
}

func main() {
	// Example price calculation script
	script := `
function calculate_final_price(ctx)
    -- Apply 10% discount for VIP users (tier >= 2)
    if ctx.user_tier >= 2 then
        return ctx.base_price * 0.9
    else
        return ctx.base_price
    end
end
`
	ctx := map[string]float64{
		"base_price": 100.0,
		"user_tier":  2.0,
	}

	price, err := ExecutePricingScript(script, ctx)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Printf("Final price: %.2f\n", price)
}

