package main

import (
	"fmt"

	lua "github.com/yuin/gopher-lua"
)

// ExecutePricingScript runs a Lua pricing script with the given context
// and returns the calculated final price as a float64.
//
// The Lua script must define a global function:
//   function calculate_final_price(ctx)
//       -- ...
//       return <number>
//   end
//
// ctx contains keys like "base_price", "user_tier" etc., all float64.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	L := lua.NewState()
	defer L.Close()

	// Execute the user-provided script
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("script execution error: %w", err)
	}

	// Get the global function
	luaFunc := L.GetGlobal("calculate_final_price")
	if luaFunc.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function (type: %s)", luaFunc.Type())
	}

	// Build Lua table from context map
	t := L.NewTable()
	for k, v := range ctx {
		L.SetField(t, k, lua.LNumber(v))
	}

	// Push function and argument, then call with 1 argument and 1 expected result
	L.Push(luaFunc) // function
	L.Push(t)       // argument

	if err := L.PCall(1, 1, nil); err != nil {
		return 0, fmt.Errorf("function call error: %w", err)
	}

	// Retrieve the return value (should be number)
	ret := L.ToNumber(-1)
	L.Pop(1) // clean stack

	return float64(ret), nil
}

func main() {
	// Example usage
	script := `
function calculate_final_price(ctx)
    if ctx.user_tier >= 2 then
        return ctx.base_price * 0.9
    else
        return ctx.base_price
    end
end
`
	context := map[string]float64{
		"base_price": 100.0,
		"user_tier":  2.0,
	}

	price, err := ExecutePricingScript(script, context)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Printf("Final price: %.2f\n", price)
	}
}

